import{bQ as s,aL as i,u as a,G as t}from"./chunks/framework.D06dwy5q.js";const r=JSON.parse('{"title":"05｜过期与内存管理","description":"","frontmatter":{},"headers":[],"relativePath":"05.Redis/05-过期与内存管理.md","filePath":"05.Redis/05-过期与内存管理.md","lastUpdated":null}'),d={name:"05.Redis/05-过期与内存管理.md"};function o(l,e,p,h,n,k){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="_05-过期与内存管理" tabindex="-1">05｜过期与内存管理 <a class="header-anchor" href="#_05-过期与内存管理" aria-label="Permalink to &quot;05｜过期与内存管理&quot;">​</a></h1><p>Redis 是内存数据库，数据全部放内存。这带来一个根本问题：内存是有限的，存进去的 key 永远不清理迟早撑爆。所以 Redis 有两套机制管内存——过 key 设过期时间让它自动消失、内存满了按策略淘汰。</p><p>这篇讲两件事：怎么给 key 设过期、内存满了怎么淘汰。前提是已经会基本操作（前面讲过 EXPIRE、SET EX）。</p><h2 id="一、过期机制-key-到期怎么删" tabindex="-1">一、过期机制：key 到期怎么删 <a class="header-anchor" href="#一、过期机制-key-到期怎么删" aria-label="Permalink to &quot;一、过期机制：key 到期怎么删&quot;">​</a></h2><p>上一篇讲过怎么给 key 设过期：<code>EXPIRE</code>、<code>SET key value EX seconds</code>。但 key 到了过期时间，是怎么被删掉的？Redis 用两种机制配合：</p><p><strong>惰性删除</strong>——访问 key 时检查一下，过期了就删。这是被动的，没有访问就没人检查。</p><p><strong>定期删除</strong>——后台每隔一段时间随机抽样一批 key，发现过期的就删。这保证没人访问的过期 key 也会被清理，不至于一直占内存。</p><p>两种机制配合的结果：key 到期不一定会被立刻删掉。没人访问、又没被定期扫描抽样到的过期 key 会暂时留着，等某次访问或扫描再删。</p><p><strong>后果一</strong>：内存里其实有不少&quot;过期了但还没被清理&quot;的 key，看 <code>INFO keyspace</code> 的 <code>expires</code> 和 <code>keys</code> 差值、<code>avg_ttl</code> 能看出端倪。</p><p><strong>后果二</strong>：大量 key 集中在同一秒过期（比如整点建的缓存全在同一时刻到期），定期删除会短时间消耗明显 CPU，可能拖慢正常命令。规划时别让大量 key 同时过期——加随机抖动：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 让过期时间分散在 300-360 秒之间，避免雷同</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">EXPIRE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cache:user:1001</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $((</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">300</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RANDOM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> %</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>这是 Redis 限流和缓存设计的常见技巧，叫&quot;过期抖动&quot;。</p><h2 id="二、过期和持久化的关系" tabindex="-1">二、过期和持久化的关系 <a class="header-anchor" href="#二、过期和持久化的关系" aria-label="Permalink to &quot;二、过期和持久化的关系&quot;">​</a></h2><p>RDB 和 AOF 的细节在下一篇专门讲，这里只带过期的关系。</p><p>设了过期的 key，重启后还在不在？</p><p>RDB 快照里：过期信息随 key 一起存。重启加载后 key 还在、带过期时间，到期会被正常淘汰。但 RDB 只保留快照那一刻还存在且未过期的 key——已经过期的不会再出现在快照里。</p><p>AOF 里：每条 EXPIRE 命令都会被记录，重放时重新设过期。考虑到期前能否重放完——AOF 重放期间 key 可能被访问，过期机制照常工作。</p><p>一个要知道的边角：RDB 快照时机和 key 是否过期有关。<code>BGSAVE</code> 把当下未过期的 key 写盘，过期的不写。所以从 RDB 恢复后，那批&quot;快照时还没过期、但现在已过期&quot;的 key 也回来了，但带着过期时间，会按上面机制清理。</p><h2 id="三、内存上限-maxmemory" tabindex="-1">三、内存上限：maxmemory <a class="header-anchor" href="#三、内存上限-maxmemory" aria-label="Permalink to &quot;三、内存上限：maxmemory&quot;">​</a></h2><p>内存有限，必须给 Redis 一个使用上限：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">maxmemory 2gb</span></span></code></pre></div><p><code>maxmemory</code> 是 Redis 使用内存的上限，达到后按淘汰策略处理新写入。不设的话 Redis 会一直吃内存直到系统 OOM，那时整个机器垮——生产必须设。</p><p>看当前用的对不对：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CONFIG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> maxmemory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> used_memory_human</span></span></code></pre></div><p><code>maxmemory</code> 单位用字节或带 K/M/G 后缀，配置文件里写成 <code>2gb</code> 也行。</p><p>设多少合适：给 Redis 留出&quot;机器总内存 - 系统占用 - 其他进程&quot;的 60-70%。如果机器是 Redis 专用，留 20% 给系统、备份、AOF 重写就够了。</p><h2 id="四、淘汰策略-内存满了怎么办" tabindex="-1">四、淘汰策略：内存满了怎么办 <a class="header-anchor" href="#四、淘汰策略-内存满了怎么办" aria-label="Permalink to &quot;四、淘汰策略：内存满了怎么办&quot;">​</a></h2><p>内存到了上限，新数据要写入时怎么决定删谁？<code>maxmemory-policy</code> 决定：</p><table tabindex="0"><thead><tr><th>策略</th><th>行为</th><th>适合</th></tr></thead><tbody><tr><td><code>noeviction</code></td><td>不淘汰，写入直接报错</td><td>不能丢任何数据</td></tr><tr><td><code>allkeys-lru</code></td><td>所有 key 中淘汰最近最少使用的</td><td>纯缓存，都可丢</td></tr><tr><td><code>volatile-lru</code></td><td>只在设了过期的 key 中淘汰</td><td>永久数据 + 缓存混合</td></tr><tr><td><code>allkeys-lfu</code></td><td>淘汰访问频率最低的（7.4 推荐）</td><td>访问模式偏斜的缓存</td></tr><tr><td><code>volatile-ttl</code></td><td>淘汰 TTL 最短的</td><td>希望长 TTL 优先保留</td></tr><tr><td><code>allkeys-random</code></td><td>随机淘汰</td><td>访问均匀的缓存</td></tr></tbody></table><p>选策略的核心问题：<strong>Redis 里的数据，哪些可以丢？</strong></p><ul><li><strong>全部可以丢</strong>（纯缓存）→ <code>allkeys-lru</code>，绝大多数缓存场景都适用，不确定就选它</li><li><strong>一部分不能丢</strong>（缓存 + 持久数据混在一台）→ <code>volatile-lru</code>。但前提是：不能丢的 key 没设过期、缓存的都设了过期，约定要在团队统一好，否则保护形同虚设</li><li><strong>都不能丢</strong>（存的是业务状态如会话、计数）→ <code>noeviction</code>，但要做好&quot;写入偶尔报错&quot;的心理准备</li></ul><h2 id="五、看淘汰有没有发生" tabindex="-1">五、看淘汰有没有发生 <a class="header-anchor" href="#五、看淘汰有没有发生" aria-label="Permalink to &quot;五、看淘汰有没有发生&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stats</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> evicted_keys</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stats</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> expired_keys</span></span></code></pre></div><p>两个数要区分清楚：</p><ul><li><code>evicted_keys</code>：因为内存满了被 maxmemory 策略踢掉的 key。<code>allkeys-lru</code> 下这是预期行为，纯缓存的实例会有这个数正常增长。</li><li><code>expired_keys</code>：因为 TTL 到期被过期机制删掉的 key。这是正常的过期删除，和内存满没关系。</li></ul><p>混在一起的判断：纯缓存的实例 <code>evicted_keys</code> 在涨，要看缓存命中率有没有掉——掉得多说明内存不够用，该扩内存了。业务状态实例 <code>evicted_keys &gt; 0</code> 是在丢数据，要立即处理。</p><h2 id="六、内存分析" tabindex="-1">六、内存分析 <a class="header-anchor" href="#六、内存分析" aria-label="Permalink to &quot;六、内存分析&quot;">​</a></h2><p>内存报警时，几个命令定位问题。</p><p>看总体：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory</span></span></code></pre></div><p>关键字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td><code>used_memory</code></td><td>Redis 分配器统计的已用内存（不含碎片）</td></tr><tr><td><code>used_memory_rss</code></td><td>操作系统看到的该进程实际占用（含碎片）</td></tr><tr><td><code>mem_fragmentation_ratio</code></td><td><code>rss / used_memory</code>，大于 1.5 说明碎片严重</td></tr><tr><td><code>maxmemory</code></td><td>配置的上限</td></tr></tbody></table><p><code>used_memory</code> 稳定但 <code>rss</code> 一直在涨，<code>mem_fragmentation_ratio</code> 高——是内存碎片。Redis 释放 key 后内存归 allocator 池不一定还给 OS，长短期 key 混存的实例常有。能重启的话重启重置碎片（但这是有损操作）。Redis 4+ 有 <code>activedefrag</code> 主动整理碎片的选项，但效果不如重启彻底。</p><p><code>used_memory</code> 自己一直涨，<code>keys</code> 数量也在涨——是真实数据增长。看是哪些类型的 key 在增多：<code>INFO keyspace</code>、<code>SCAN</code> 抽样，找没设过期的&quot;僵尸 key&quot;。</p><p>看 key 空间分布：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keyspace</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># db0:keys=120000,expires=90000,avg_ttl=3600000</span></span></code></pre></div><p><code>keys</code> 是当前 key 总数，<code>expires</code> 是其中设了过期的。<code>keys</code> 大但 <code>expires</code> 极小，说明大部分 key 没设过期——这些没过期的 key 是吃内存的主因。要么是有意存的永久数据，要么是忘设过期的缓存慢慢累积，某天就 OOM。</p><h2 id="七、找没有过期的-key" tabindex="-1">七、找没有过期的 key <a class="header-anchor" href="#七、找没有过期的-key" aria-label="Permalink to &quot;七、找没有过期的 key&quot;">​</a></h2><p>内存涨但找不到元凶时，scan 一下找没设过期的 key：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --scan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pattern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;cache:*&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -20</span></span></code></pre></div><p>然后对每个怀疑的 key 看 TTL：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TTL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cache:user:1001</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># -1 表示永久（没有过期），-2 表示 key 不存在</span></span></code></pre></div><p><code>-1</code> 的多，说明这一类 key 没设过期，要么主动改设过期，要么排查应用代码为什么没设 TTL。</p><h2 id="八、一个完整的内存排查思路" tabindex="-1">八、一个完整的内存排查思路 <a class="header-anchor" href="#八、一个完整的内存排查思路" aria-label="Permalink to &quot;八、一个完整的内存排查思路&quot;">​</a></h2><p>内存报警，按这个顺序查：</p><ol><li><code>INFO memory</code>：看 <code>used_memory</code> 和 <code>rss</code> 谁涨——是数据增长还是碎片</li><li><code>INFO keyspace</code>：看 <code>keys</code> 和 <code>expires</code> 比例——大量无过期的 key 是元凶</li><li><code>INFO stats</code>：看 <code>evicted_keys</code> 是否在涨——确认是否已经触顶淘汰</li><li>SCAN 找具体的&quot;僵尸 key&quot;类</li><li>决定：补过期时间、扩 maxmemory、还是清僵尸 key</li></ol><p>每一步用一条命令拿到一个事实，不要凭感觉猜。</p><p>过期和淘汰是管理内存的两个机制：用 <code>EXPIRE</code> 让 key 自然消失、用 <code>maxmemory</code> + 淘汰策略防止内存撑爆。<code>volatile-lru</code>、<code>allkeys-lru</code>、<code>noeviction</code> 三种策略按&quot;哪些数据可丢&quot;区分场景。<code>INFO memory</code>、<code>INFO keyspace</code>、<code>evicted_keys</code>/<code>expired_keys</code> 是内存排查的入口。</p><p>下一篇讲持久化——内存数据怎么存盘不死。</p>`,59)])])}const y=s(d,[["render",o]]);export{r as __pageData,y as default};
